from lib import *
S = SS('k20')
F1 = [['kubectl create token', 'POST …/token'], ['有效期', '默认 3600,最短 600'], ['签发 JWT', 'exp-iat = 请求的秒数']]
F2 = [['aud=API Server', '可以调用 API'], ['aud=my-service', 'API Server 401'], ['TokenReview', '带 audiences 才通过'], ['签名被改', 'invalid bearer token']]
F3 = [['令牌绑定 Pod', 'kubernetes.io.pod'], ['删除 Pod', ''], ['10 秒内', '仍然通过'], ['第 11 秒起', '401']]
F4 = [['TokenReview', 'authenticated=true'], ['user', 'system:serviceaccount:k20:app'], ['groups', '3 个'], ['audiences', 'API Server 的受众']]
PANELS = [('f', 'flow', 'TokenRequest'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("kubectl create token:不指定有效期 exp-iat=3600 秒;--duration=20m → 1200 秒;--duration=10m → 600 秒(下限);--duration=5m → 退出码 1,Invalid value: 300: may not specify a duration less than 10 minutes;--duration=87600h(10 年)被接受,exp-iat=315360000 秒——这个集群没有给令牌有效期设上限。默认受众是 https://kubernetes.default.svc.cluster.local。", f=fl(F1, cur=[1], done=[0, 2]), t=tl(S(1), mark=lidx(S(1), '5m(低于下限)', '10 年'), done=lidx(S(1), '不指定(默认)', '10m(下限)')), kv=KV([['默认', '1 小时'], ['下限', '10 分钟'], ['上限', '取决于 apiserver 参数,本集群没有限制']], ['上限'])),
    step("同一个 ServiceAccount 的两个令牌:默认受众的令牌调用 API Server 得到 HTTP 201;--audience=my-service 的令牌调用 API Server 得到 401(API Server 不认这个受众)。用 TokenReview 验证:带 spec.audiences=[my-service] 时 authenticated=True;不带(按 API Server 自己的受众)authenticated=False,error 是 token audiences [\"my-service\"] is invalid for the target audiences;把令牌最后 6 个字符改掉得到 invalid bearer token, go-jose/go-jose: error in cryptographic primitive。", f=fl(F2, cur=[1, 2], done=[0], mark=[3]), t=tl(S(2), mark=lidx(S(2), 'HTTP 401', 'authenticated=False'), done=lidx(S(2), 'authenticated=True', 'HTTP 201')), kv=KV([['aud', '这个令牌是发给谁用的'], ['API Server 只认自己的受众', '其他服务用 TokenReview 并带上自己的 audiences'], ['签名', '改一个字符就验不过']], ['aud'])),
    step("绑定对象:把 SA other 的令牌绑到 SA app 的 Pod 上被拒(cannot bind token … to pod running with different serviceaccount name);SA app 的令牌绑定 Pod holder 后,claims 里有 kubernetes.io.pod={name: holder, uid},调用 API 的 extra 里带 pod-name、node-name 等。删除 Pod holder 之后令牌还能再用 10 秒,第 11 秒起 HTTP 401;没有绑定对象的 t_def 一直有效;给 SA temp 签的令牌,删掉 SA temp 后同样在第 11 秒起 401。", f=fl(F3, cur=[1], mark=[3], done=[0, 2]), t=tl(S(3), mark=lidx(S(3), '第 11 秒起'), done=lidx(S(3), '--bound-object-kind=Pod', '同一时刻')), kv=KV([['绑定对象', '对象没了令牌就作废'], ['不是立刻', '删除后约 10 秒才开始返回 401'], ['绑定 SA', '签发时总是绑定 SA 本身']], ['不是立刻'])),
    step("TokenReview 看到的信息:authenticated=True;user.username=system:serviceaccount:k20:app,user.uid=ServiceAccount 的 uid,user.groups=[system:serviceaccounts, system:serviceaccounts:k20, system:authenticated];status.audiences=[API Server 的受众];user.extra 里有 authentication.kubernetes.io/credential-id: JTI=…。", f=fl(F4, cur=[1, 2]), t=tl(S(4), mark=lidx(S(4), 'user.username'), done=lidx(S(4), 'status.audiences')), kv=KV([['username', 'system:serviceaccount:<ns>:<name>'], ['groups', '全部 SA / 本命名空间 SA / 已认证'], ['credential-id', '令牌的 jti,用来做审计']], ['groups'])),
]
A = mkartk('k20', 20, 'Kubernetes,TokenRequest,ServiceAccount,kubectl create token,TokenReview,真实验证,动画演示',
    '在 kind 集群里实测 TokenRequest:kubectl create token 默认 1 小时、最短 10 分钟(5 分钟被拒)、本集群接受 10 年;audience 不是 API Server 的令牌调用 API 得到 401,但可用带 audiences 的 TokenReview 验证;令牌可绑定到 Pod,Pod 或 ServiceAccount 删除后令牌再过约 10 秒才开始返回 401;TokenReview 返回 username、uid、groups 与 credential-id。',
    'kubectl create token 背后的 TokenRequest 做了什么?它签出的令牌有效期、受众、绑定对象各有什么约束?删掉 Pod 之后令牌会立刻失效吗?这篇逐条实测,并用 TokenReview 看一个令牌在服务端被解析成什么样子。',
    [('600 秒', '令牌有效期的下限,请求 5 分钟被拒绝(默认 3600 秒)'), ('第 11 秒', '删除被绑定的 Pod(或 SA)后,令牌从这一秒起开始返回 401,之前的 10 秒内仍然有效'), ('315360000 秒', '--duration=87600h(10 年)被接受:本集群没有给令牌有效期设上限')],
    [('有效期', '<p><code>kubectl create token app</code> 默认签出有效期 3600 秒的 JWT(<code>exp - iat = 3600</code>),<code>--duration=20m</code> 就是 1200 秒,<code>--duration=10m</code> 是下限 600 秒;<code>5m</code> 被拒:<code>may not specify a duration less than 10 minutes</code>。上限由 apiserver 的参数决定,这个集群没有设,连 10 年(<code>87600h</code>)都被接受。需要短期令牌的场景要自己限制,不能指望服务端兜底。</p>'),
     ('受众', '<p>令牌的 <code>aud</code> 声明说明它是发给谁用的。默认令牌的受众是 API Server(<code>https://kubernetes.default.svc.cluster.local</code>),可以调用 API;<code>--audience=my-service</code> 的令牌受众是别的服务,拿去调 API Server 得到 401。其他服务要验证它,调用 TokenReview 并带上自己的 <code>spec.audiences</code>:带上 <code>[my-service]</code> 得到 <code>authenticated=True</code>,不带则得到 <code>token audiences ["my-service"] is invalid for the target audiences</code>。令牌末尾改掉几个字符就是 <code>invalid bearer token</code>(签名校验失败)。</p>'),
     ('绑定对象', '<p>令牌可以绑定到 Pod、Secret 等对象(<code>--bound-object-kind</code> / <code>--bound-object-name</code>);绑定的 Pod 必须使用同一个 ServiceAccount,否则签发就被拒绝。绑定后 claims 里有 <code>kubernetes.io.pod</code>(名字和 uid),调用 API 时 <code>user.extra</code> 里带 <code>pod-name</code>、<code>node-name</code> 等。对象删除后令牌失效,但不是立刻:这次实测删除之后又过了 10 秒仍通过认证,第 11 秒起才 401。没有绑定对象的令牌绑定的是 ServiceAccount 本身,SA 删了同样如此。</p>'),
     ('TokenReview', '<p>TokenReview 把令牌解析成身份:<code>username=system:serviceaccount:k20:app</code>,<code>groups</code> 是 <code>system:serviceaccounts</code>、<code>system:serviceaccounts:k20</code>、<code>system:authenticated</code>,<code>status.audiences</code> 是这次验证命中的受众,<code>user.extra</code> 里的 <code>credential-id: JTI=…</code> 是令牌的 jti,方便审计日志对应。</p>')],
    steps,
    [ENV_K + '。三节点 kind 集群 kx-main(Kubernetes v1.37.0,apiserver 没有设置 --service-account-max-token-expiration);令牌用 kubectl create token 签发,claims 在宿主机上解 JWT;调用 API 用 SelfSubjectReview(POST /apis/authentication.k8s.io/v1/selfsubjectreviews,宿主机 Python 直连 apiserver 的回环端口,带 Bearer 令牌),验证用 TokenReview;“失效时间”由每秒一次的轮询得到,删除对象后第一个 401 出现在第 11 秒(另一次探测也是 12 秒左右);每种情形各一次',
     '没有验证:令牌过期本身(最短 10 分钟,没有等到过期);apiserver 参数 --service-account-max-token-expiration 设置后的截断;--service-account-extend-token-expiration;对 Secret、Node 的绑定;10 秒左右的延迟具体来自 apiserver 的哪个缓存(只观察到现象);JWKS 公钥发现端点(/openid/v1/jwks)'],
    'TokenRequest', PANELS)
